const evidence=$('Prepare Candidate Evidence').all();
return $input.all().map((item,i)=>({json:normalizeRecord(item.json.output||item.json,evidence[i].json,evidence[i].json),pairedItem:{item:i}}));

const ctx=$('Build Research Context').first().json;
const currencies=[...new Set($input.all().map(i=>i.json).filter(r=>r.usable&&r.currency!==ctx.target.currency&&!ctx.fx_rates?.[r.currency]).map(r=>r.currency))].slice(0,3);
if(!currencies.length)return [{json:{needs_fx:false}}];
return currencies.map(currency=>({json:{needs_fx:true,currency,target_currency:ctx.target.currency,period:ctx.target.fiscal_year,
query:ctx.target.fiscal_year+' annual average exchange rate 1 '+currency+' to '+ctx.target.currency+' central bank'}}));

function validateFx(raw, evidence) {
  const clean=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
  const source=evidence.sources.find(s=>s.url===raw.source_url);
  const quote=clean(raw.evidence_excerpt),rate=Number(raw.rate);
  const from=evidence.currency.toLowerCase(),to=evidence.target_currency.toLowerCase();
  // An unlabelled table value is insufficient: it may be an inverse rate or another currency.
  const pair=new RegExp('\\b'+from+'\\s*(?:/|to|→|-)\\s*'+to+'\\b');
  const equation=new RegExp('\\b1(?:\\.0+)?\\s*'+from+'\\s*(?:=|equals)\\s*[0-9.,]+\\s*'+to+'\\b');
  const directed=pair.test(quote)||equation.test(quote);
  const annual=/annual|yearly|year average|year-average/.test(quote)&&/average/.test(quote);
  const usable=!!source&&quote.length>10&&clean(source.text).includes(quote)&&
    /^\d+(?:\.\d+)?$/.test(raw.rate||'')&&Number.isFinite(rate)&&rate>0&&
    quote.includes(raw.rate)&&quote.includes(evidence.period)&&directed&&annual;
  return {currency:evidence.currency,usable,to_target:usable?rate:null,
    target_currency:evidence.target_currency,period:evidence.period,source_url:raw.source_url,
    evidence_excerpt:raw.evidence_excerpt,evidence_level:'search_snippet',
    issue:usable?'':'Annual average, year, rate, and currency direction are not all explicitly supported'};
}

const evidence=$('Prepare FX Evidence').all();
return $input.all().map((item,i)=>({json:validateFx(item.json.output||item.json,evidence[i].json)}));

function rankPeers(context, records) {
  const target = context.target;
  const clean = s => String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const excluded = [], eligible = [], seen = new Set([clean(target.company)]);
  for (const record of records) {
    const r = {...record, exclusion_reasons:[...(record.issues || [])]};
    const key = clean(r.company), group = clean(r.parent_group || r.company);
    if (!key || seen.has(key) || seen.has(group)) r.exclusion_reasons.push('Self, duplicate, or repeated parent group');
    seen.add(key); seen.add(group);
    if (r.sector_fit !== 'same') r.exclusion_reasons.push('Sector fit requires review');
    if (!target.usable) r.exclusion_reasons.push('Target revenue evidence is incomplete');
    if (r.fiscal_year !== target.fiscal_year) r.exclusion_reasons.push('Fiscal year differs from target');
    let rate = 1;
    if (r.currency !== target.currency) {
      const fx = context.fx_rates?.[r.currency];
      if (!fx || !(fx.to_target > 0) || !Number.isFinite(fx.to_target) ||
          fx.target_currency !== target.currency || String(fx.period) !== target.fiscal_year ||
          !/^https:\/\//.test(fx.source_url || '')) {
        r.exclusion_reasons.push('Sourced annual-average currency conversion is missing');
        rate = null;
      } else {
        rate = fx.to_target;
        r.fx_evidence = fx;
      }
    }
    r.revenue_in_target_currency = rate !== null && r.revenue_base_units > 0 ? r.revenue_base_units * rate : null;
    r.revenue_ratio = target.revenue_base_units > 0 && r.revenue_in_target_currency > 0
      ? r.revenue_in_target_currency / target.revenue_base_units : null;
    if (r.revenue_ratio === null || r.revenue_ratio < context.ratio_min || r.revenue_ratio > context.ratio_max)
      r.exclusion_reasons.push('Outside chosen revenue range or not comparable');
    r.distance = r.revenue_ratio > 0 ? Math.abs(Math.log(r.revenue_ratio)) : null;
    r.exclusion_reasons = [...new Set(r.exclusion_reasons)];
    (r.exclusion_reasons.length ? excluded : eligible).push(r);
  }
  eligible.sort((a,b)=>a.distance-b.distance || a.company.localeCompare(b.company));
  const selected = eligible.slice(0,5).map((r,i)=>({...r,rank:i+1}));
  return {status:'awaiting_human_review', company:target.company, sector:context.sector,
    geography:context.geography, research_window:context.research_window, target,
    criteria:{ratio_min:context.ratio_min,ratio_max:context.ratio_max,matching_fiscal_year:target.fiscal_year,
      currency:target.currency,ranking:'absolute natural log of peer-to-target revenue ratio'},
    selected_peers:selected, alternatives:eligible.slice(5), excluded_candidates:excluded,
    selected_count:selected.length, shortfall:Math.max(0,5-selected.length),
    limitations:[
      'Selection is provisional until you verify original financial sources and sector/parent-group fit.',
      'Search snippets are preliminary evidence. Uploaded report text is not independently authenticated.',
      'Missing figures, mismatched fiscal years, unknown sector fit, and missing FX sources are excluded.',
      'Fiscal-year labels are compared; differing year-end dates still require human review.',
      'Geography and parent-group relationships are model assessments requiring review.'
    ],
    next_action:selected.length<5?'Review exclusions, supply missing evidence/FX, or explicitly widen criteria.':'Review the five proposed peers.'};
}

const ctx=JSON.parse(JSON.stringify($('Build Research Context').first().json));let records=[];
try{records=$('Normalize Candidate Revenues').all().map(i=>i.json);}catch{}
try{for(const x of $('Validate FX Evidence').all().map(i=>i.json)){if(x.usable&&!ctx.fx_rates[x.currency])ctx.fx_rates[x.currency]=x;}}catch{}
const briefing=rankPeers(ctx,records);
briefing.review_instructions='Review source quotations/URLs, sector and geography fit, parent groups, year-end dates and FX before approving. A shortfall requires explicit acknowledgement.';
briefing.discovery_limitations=$('Validate Peer Candidates').first().json.output.limitations;
briefing.review_url=null;
return [{json:briefing}];

const draft=$('Rank Revenue Peers').first().json;
if(draft.target?.usable!==true)throw Error('Target annual revenue failed evidence checks; automatic selection cannot continue');
const selected=draft.selected_peers||[];
if(selected.some(p=>p.usable===false||(p.exclusion_reasons||[]).length))throw Error('A selected peer failed automated evidence checks');
return [{json:{...draft,review_url:null,status:draft.shortfall?'approved_with_gaps':'approved',approved:true,
 review:{approval_mode:'user_authorized_automatic',decision:'Approve',sources_verified:false,source_validation:'automated quotation, number, year, currency, revenue-range and sector checks; original sources not independently verified',accept_shortfall:true,notes:'User explicitly waived pre-approval. Unresolved evidence and fewer than five eligible peers remain reported as gaps.'},
 next_action:'Continue research automatically; retain evidence limitations in the final briefing.',
 companies_for_agent2:[{company:draft.company,is_target:true},...selected.map(p=>({company:p.company,is_target:false,source_url:p.source_url}))]}}];

function makeBriefing(peerBriefing,research,history,runId,runTime,mode='research',leaderRows=[]) {
  if(mode==='research'&&peerBriefing?.approved!==true)throw new Error('Peer research requires an approved briefing');
  const normalize=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
  const company=peerBriefing?.company||research.companies?.[0]||'Company research';
  const companyKey=normalize(company);
  const snapshots=history.filter(r=>r.company_key===companyKey&&r.record_type===(mode==='preview'?'research_preview':'research_snapshot'))
    .sort((a,b)=>String(b.run_time).localeCompare(String(a.run_time)));
  let previous=null;for(const row of snapshots){try{previous=JSON.parse(row.payload_json);break;}catch{}}
  const records=research.evidence_records||[];
  const analyses=research.analysis_results||[];
  const signals=analyses.flatMap(a=>(a.signals||[]).map(s=>({...s,company:a.company,evidence_level:a.evidence_level,publication_date:a.publication_date})));
  const identity=s=>[s.company,s.source_url,s.category,s.person,s.vendor_or_technology].map(normalize).join('|');
  const priorSignals=new Map((previous?.signals||[]).map(s=>[identity(s),s]));
  const changed=[],newSignals=[];
  for(const s of signals){const old=priorSignals.get(identity(s));if(!old)newSignals.push(s);
    else if(['status','summary','effective_date','contract_value'].some(k=>s[k]!==old[k]))changed.push({before:old,after:s});}
  const sources=new Map();
  function source(url,title,date,level){if(!url||!/^https?:\/\//.test(url))return;
    if(!sources.has(url))sources.set(url,{id:'S'+String(sources.size+1).padStart(3,'0'),url,title:title||url,date:date||'not found',level:level||'public evidence'});}
  const financialEvidenceLevel=peerBriefing?.review?.approval_mode==='user_authorized_automatic'?'automated financial checks; original-source verification pending':'human-reviewed financial evidence';
  source(peerBriefing?.target?.source_url,'Target annual revenue',peerBriefing?.target?.fiscal_year,financialEvidenceLevel);
  for(const p of peerBriefing?.selected_peers||[])source(p.source_url,p.company+' revenue',p.fiscal_year,financialEvidenceLevel);
  for(const r of [...records,...(research.review_queue||[])])source(r.source_url,r.title,r.publication_date,r.evidence_level);
  for(const s of signals){source(s.source_url,s.summary,s.publication_date,s.evidence_level);s.citation_id=sources.get(s.source_url)?.id||'unresolved';}
  const priorSourceUrls=new Set((previous?.sources||[]).map(s=>s.url));
  const companies=research.companies||[company,...(peerBriefing?.selected_peers||[]).map(p=>p.company)];
  const leadership=[];
  const leaderCompanies=new Set(companies.map(normalize));
  const seenLeaders=new Set();
  for(const row of [...leaderRows].sort((a,b)=>String(b.run_time).localeCompare(String(a.run_time)))){
    if(row.record_type!=='leadership_background'||!leaderCompanies.has(normalize(row.company_key))||seenLeaders.has(row.company_key))continue;
    try{const saved=JSON.parse(row.payload_json);seenLeaders.add(row.company_key);
      for(const r of saved.discovery_sources||[])source(r.source_url,r.title,r.publication_date,'saved leader search snippet');
      for(const profile of saved.profiles||[])for(const link of profile.linkedin_profiles||[])source(link.source_url,profile.person_name+' — public LinkedIn search result','not found','public LinkedIn search snippet');
      for(const profile of saved.profiles||[])for(const c of profile.claims||[]){source(c.source_url,c.statement,'not found','saved background search snippet');c.citation_id=sources.get(c.source_url)?.id||'unresolved';}
      leadership.push({...saved,saved_run_id:row.run_id,saved_at:row.run_time,background_note:'Saved historical background, not fresh or independently verified current-role evidence.'});
    }catch{ /* Malformed old memory is not reused as evidence. */ }
  }
  return {schema_version:1,mode,leadership_background:leadership,leadership_missing:companies.filter(c=>!leadership.some(p=>normalize(p.company_name)===normalize(c))),run_id:runId,run_time:runTime,research_date:new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(runTime)),company,company_key:companyKey,
    sector:peerBriefing?.sector||'not specified',geography:peerBriefing?.geography||'not specified',
    research_window:research.research_window||peerBriefing?.research_window||{},
    peer_selection:peerBriefing||null,companies,signals,sources:[...sources.values()],
    coverage:research.coverage||[],statistics:research.statistics||{},analysis_statistics:research.analysis_statistics||{},
    company_findings:companies.map(name=>({company:name,signals:signals.filter(s=>normalize(s.company)===normalize(name)),
      coverage:(research.coverage||[]).find(c=>normalize(c.company)===normalize(name))||null})),
